/* ============================================================
   Browser OS — Stylesheet
   Modern flat design (Windows 11 / macOS style)
   ============================================================ */

/* ---------- Reset ---------- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  color: #1e1e1e;
  user-select: none;
  -webkit-user-select: none;
}

/* ============================================================
   Desktop
   ============================================================ */
#desktop {
  position: fixed;
  inset: 0;
  z-index: 0;
  background: #3a6b8c;
  transition: background 0.3s ease;
}

/* ---------- Wallpaper presets ---------- */
/* 1. Default teal */
.wallpaper-0 {
  background: linear-gradient(135deg, #1a5276, #3a6b8c, #1a5276);
}

/* 2. Purple */
.wallpaper-1 {
  background: linear-gradient(135deg, #4a148c, #7b1fa2, #4a148c);
}

/* 3. Sunset orange */
.wallpaper-2 {
  background: linear-gradient(135deg, #bf360c, #e65100, #ff6e40);
}

/* 4. Forest green */
.wallpaper-3 {
  background: linear-gradient(135deg, #1b5e20, #388e3c, #1b5e20);
}

/* 5. Midnight blue */
.wallpaper-4 {
  background: linear-gradient(135deg, #0d1b2a, #1b263b, #0d1b2a);
}

/* 6. Rose */
.wallpaper-5 {
  background: linear-gradient(135deg, #880e4f, #c2185b, #880e4f);
}

/* 7. Light solid */
.wallpaper-6 {
  background: #e8e8e8;
}

/* 8. Dot pattern */
.wallpaper-7 {
  background: #263238;
  background-image: radial-gradient(circle, #37474f 1px, transparent 1px);
  background-size: 24px 24px;
}

/* ============================================================
   Desktop Icons
   ============================================================ */
#desktop-icons {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 90px;
  border-radius: 8px;
  cursor: pointer;
  padding: 8px 4px;
  transition: background 0.15s ease;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.12);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.2);
}

.desktop-icon-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 6px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
}

.desktop-icon-label {
  font-size: 11px;
  color: #ffffff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  text-align: center;
  word-wrap: break-word;
  line-height: 1.3;
}

/* Icon colors */
.desktop-icon[data-app="notepad"] .desktop-icon-icon {
  background: #2196F3;
}

.desktop-icon[data-app="calculator"] .desktop-icon-icon {
  background: #FF5722;
}

.desktop-icon[data-app="minesweeper"] .desktop-icon-icon {
  background: #4CAF50;
}

.desktop-icon[data-app="spider"] .desktop-icon-icon {
  background: #9C27B0;
}

/* ============================================================
   Windows Container
   ============================================================ */
#windows-container {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
}

/* ============================================================
   Window
   ============================================================ */
.window {
  position: absolute;
  min-width: 320px;
  min-height: 200px;
  background: #f5f5f5;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  pointer-events: auto;
  overflow: hidden;
  transition: box-shadow 0.15s ease;
}

.window.focused {
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
}

/* ---------- Title Bar ---------- */
.window-titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 38px;
  padding: 0 12px;
  background: #e8e8e8;
  cursor: grab;
  border-radius: 10px 10px 0 0;
}

.window.focused .window-titlebar {
  background: #ffffff;
}

.window-titlebar.dragging {
  cursor: grabbing;
}

.window-title-text {
  font-size: 13px;
  font-weight: 500;
  color: #1e1e1e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  margin-right: 8px;
}

.window-title-text .window-extra {
  font-weight: 400;
  color: #666;
  margin-left: 4px;
}

/* ---------- Window Controls ---------- */
.window-controls {
  display: flex;
  gap: 8px;
  align-items: center;
}

.window-close-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: #666;
  transition: background 0.15s ease, color 0.15s ease;
}

.window-close-btn:hover {
  background: #e0e0e0;
  color: #333;
}

.window.focused .window-close-btn {
  color: #1e1e1e;
}

/* ---------- Resize Handle ---------- */
.window-resize-handle {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
}

/* ---------- Window Content ---------- */
.window-content {
  flex: 1;
  overflow: auto;
  padding: 12px;
  font-size: 14px;
  background: #ffffff;
}

/* ---------- Placeholder content ---------- */
.placeholder-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: #888;
  gap: 12px;
}

.placeholder-content .placeholder-icon {
  font-size: 48px;
  opacity: 0.5;
}

.placeholder-content .placeholder-text {
  font-size: 16px;
}

/* ============================================================
   Taskbar
   ============================================================ */
#taskbar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: rgba(243, 243, 243, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  display: flex;
  align-items: center;
  padding: 0 8px;
  z-index: 100;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
}

/* ---------- Start Button ---------- */
#taskbar-start {
  width: 48px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  cursor: pointer;
  font-size: 20px;
  transition: background 0.15s ease;
}

#taskbar-start:hover {
  background: rgba(0, 0, 0, 0.06);
}

/* ---------- Taskbar Apps ---------- */
#taskbar-apps {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
  padding: 0 8px;
}

.taskbar-btn {
  height: 36px;
  padding: 0 16px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  color: #1e1e1e;
  white-space: nowrap;
  transition: background 0.15s ease;
  display: flex;
  align-items: center;
  gap: 6px;
}

.taskbar-btn:hover {
  background: rgba(0, 0, 0, 0.06);
}

.taskbar-btn.active {
  background: rgba(0, 0, 0, 0.08);
}

.taskbar-btn.active::after {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0078d4;
}

.taskbar-btn-icon {
  font-size: 14px;
}

/* ---------- Clock ---------- */
#taskbar-clock {
  padding: 0 16px;
  font-size: 12px;
  font-weight: 500;
  color: #1e1e1e;
  min-width: 70px;
  text-align: right;
  border-radius: 6px;
  cursor: default;
  transition: background 0.15s ease;
}

#taskbar-clock:hover {
  background: rgba(0, 0, 0, 0.06);
}

/* ============================================================
   Context Menu
   ============================================================ */
.context-menu {
  position: fixed;
  min-width: 200px;
  background: #ffffff;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
  padding: 6px;
  z-index: 1000;
  display: none;
}

.context-menu.visible {
  display: block;
}

.context-menu-item {
  padding: 8px 16px;
  font-size: 13px;
  cursor: pointer;
  border-radius: 6px;
  transition: background 0.1s ease;
}

.context-menu-item:hover {
  background: #f0f0f0;
}

.context-menu-item:active {
  background: #e0e0e0;
}

.context-menu-separator {
  height: 1px;
  background: #e0e0e0;
  margin: 4px 8px;
}

/* ============================================================
   Wallpaper Picker
   ============================================================ */
.wallpaper-picker {
  position: fixed;
  bottom: 56px;
  right: 8px;
  background: #ffffff;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
  padding: 12px;
  z-index: 1001;
  display: none;
}

.wallpaper-picker.visible {
  display: block;
}

.wallpaper-picker-title {
  font-size: 13px;
  font-weight: 600;
  color: #1e1e1e;
  margin-bottom: 10px;
}

.wallpaper-picker-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.wallpaper-option {
  width: 56px;
  height: 56px;
  border-radius: 8px;
  cursor: pointer;
  border: 2px solid transparent;
  transition: border-color 0.15s ease, transform 0.1s ease;
}

.wallpaper-option:hover {
  transform: scale(1.05);
}

.wallpaper-option.selected {
  border-color: #0078d4;
}

/* ============================================================
   Browser OS — Main JavaScript
   ============================================================ */

// ============================================================
// SECTION 1: App Registry
// ============================================================

const APPS = {
  notepad: { name: "Notepad", icon: "📝", defaultWidth: 500, defaultHeight: 360 },
  calculator: { name: "Calculator", icon: "🧮", defaultWidth: 320, defaultHeight: 440 },
  minesweeper: { name: "Minesweeper", icon: "💣", defaultWidth: 500, defaultHeight: 500 },
  spider: { name: "Spider Solitaire", icon: "🕷️", defaultWidth: 860, defaultHeight: 560 },
};

// ============================================================
// SECTION 2: Desktop Shell
// ============================================================

/**
 * Create desktop icons for each app.
 */
function createDesktopIcons() {}

/**
 * Handle double-click on a desktop icon: open or focus the app window.
 */
function handleDesktopIconDoubleClick(appId) {}

// ============================================================
// SECTION 3: Window Manager
// ============================================================

/**
 * Track z-order: highest number = frontmost.
 */
let currentZIndex = 100;

/**
 * Track focused window ID.
 */
let focusedWindowId = null;

/**
 * Map of appId -> windowId (for single-instance enforcement).
 */
const windowMap = {};

/**
 * Open a window for the given app. Returns the window DOM element.
 * If a window for this app already exists, focuses it instead.
 */
function openWindow(appId) {}

/**
 * Create a window element and add it to the DOM.
 */
function createWindowElement(appId, title, extra) {}

/**
 * Focus (raise) a window to the top of the z-order.
 */
function focusWindow(windowId) {}

/**
 * Close a window by its ID.
 */
function closeWindow(windowId) {}

// ============================================================
// SECTION 4: Window Dragging
// ============================================================

/**
 * Initialize dragging for a window's title bar.
 */
function initWindowDrag(windowElement, titleBar) {}

/**
 * Handle mouse move during window drag.
 */
function handleWindowDragMove(dx, dy, windowElement) {}

/**
 * Handle mouse up after window drag — constrain to viewport.
 */
function handleWindowDragEnd(windowElement) {}

// ============================================================
// SECTION 5: Window Resizing
// ============================================================

/**
 * Initialize resizing for a window.
 */
function initWindowResize(windowElement) {}

/**
 * Handle mouse move during window resize.
 */
function handleWindowResizeMove(dx, dy, windowElement) {}

/**
 * Handle mouse up after window resize.
 */
function handleWindowResizeEnd(windowElement) {}

// ============================================================
// SECTION 6: Taskbar
// ============================================================

/**
 * Update the taskbar to reflect current open windows.
 */
function updateTaskbar() {}

/**
 * Handle a taskbar button click — focus the corresponding window.
 */
function handleTaskbarButtonClick(windowId) {}

/**
 * Update the clock display.
 */
function updateClock() {}

// ============================================================
// SECTION 7: Context Menu (Right-click on desktop)
// ============================================================

/**
 * Show the wallpaper context menu.
 */
function showContextMenu(x, y) {}

/**
 * Hide the context menu.
 */
function hideContextMenu() {}

// ============================================================
// SECTION 8: Wallpaper
// ============================================================

/**
 * Set the desktop wallpaper by preset index.
 */
function setWallpaper(presetIndex) {}

/**
 * Show the wallpaper picker.
 */
function showWallpaperPicker() {}

/**
 * Hide the wallpaper picker.
 */
function hideWallpaperPicker() {}

// ============================================================
// SECTION 9: Initialization
// ============================================================

/**
 * Initialize the entire desktop shell.
 */
function init() {
  createDesktopIcons();
  updateClock();
  setInterval(updateClock, 1000);
  restoreWallpaper();
}

/**
 * Restore wallpaper from localStorage.
 */
function restoreWallpaper() {}

// ============================================================
// EVENT LISTENERS (set up after DOM ready)
// ============================================================

document.addEventListener("DOMContentLoaded", () => {
  init();

  // Close context menu / wallpaper picker on outside click
  document.addEventListener("click", (e) => {
    hideContextMenu();
    hideWallpaperPicker();
  });

  // Prevent context menu on the desktop
  document.getElementById("desktop").addEventListener("contextmenu", (e) => {
    e.preventDefault();
    showContextMenu(e.clientX, e.clientY);
  });
});

