  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 38px;
  padding: 0 12px;
  background: #e8e8e8;
  cursor: grab;
  border-radius: 10px 10px 0 0;
}

.window.focused .window-titlebar {
  background: #ffffff;
}

.window-titlebar.dragging {
