/* ============================================================
   Browser OS — Stylesheet
   Modern flat design (Windows 11 / macOS style)
   ============================================================ */

/* ---------- Reset ---------- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  color: #1e1e1e;
  user-select: none;
  -webkit-user-select: none;
}

/* ============================================================
   Desktop
   ============================================================ */
#desktop {
  position: fixed;
  inset: 0;
  z-index: 0;
  background: #3a6b8c;
  transition: background 0.3s ease;
}

/* ---------- Wallpaper presets ---------- */
/* 1. Default teal */
.wallpaper-0 {
  background: linear-gradient(135deg, #1a5276, #3a6b8c, #1a5276);
}

/* 2. Purple */
.wallpaper-1 {
  background: linear-gradient(135deg, #4a148c, #7b1fa2, #4a148c);
}

/* 3. Sunset orange */
.wallpaper-2 {
  background: linear-gradient(135deg, #bf360c, #e65100, #ff6e40);
}

/* 4. Forest green */
.wallpaper-3 {
  background: linear-gradient(135deg, #1b5e20, #388e3c, #1b5e20);
}

/* 5. Midnight blue */
.wallpaper-4 {
  background: linear-gradient(135deg, #0d1b2a, #1b263b, #0d1b2a);
}

/* 6. Rose */
.wallpaper-5 {
  background: linear-gradient(135deg, #880e4f, #c2185b, #880e4f);
}

/* 7. Light solid */
.wallpaper-6 {
  background: #e8e8e8;
}

/* 8. Dot pattern */
.wallpaper-7 {
  background: #263238;
  background-image: radial-gradient(circle, #37474f 1px, transparent 1px);
  background-size: 24px 24px;
}

/* ============================================================
   Desktop Icons
   ============================================================ */
#desktop-icons {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 90px;
  border-radius: 8px;
  cursor: pointer;
  padding: 8px 4px;
  transition: background 0.15s ease;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.12);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.2);
}

.desktop-icon-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 6px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
}

.desktop-icon-label {
  font-size: 11px;
  color: #ffffff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  text-align: center;
  word-wrap: break-word;
  line-height: 1.3;
}

/* Icon colors */
.desktop-icon[data-app="notepad"] .desktop-icon-icon {
  background: #2196F3;
}

.desktop-icon[data-app="calculator"] .desktop-icon-icon {
  background: #FF5722;
}

.desktop-icon[data-app="minesweeper"] .desktop-icon-icon {
  background: #4CAF50;
}

.desktop-icon[data-app="spider"] .desktop-icon-icon {
  background: #9C27B0;
}

/* ============================================================
   Windows Container
   ============================================================ */
#windows-container {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
}

/* ============================================================
   Window
   ============================================================ */
.window {
  position: absolute;
  min-width: 320px;
  min-height: 200px;
  background: #f5f5f5;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  pointer-events: auto;
  overflow: hidden;
  transition: box-shadow 0.15s ease;
}

.window.focused {
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
}

/* ---------- Title Bar ---------- */
.window-titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 38px;
  padding: 0 12px;
  background: #e8e8e8;
  cursor: grab;
  border-radius: 10px 10px 0 0;
}

.window.focused .window-titlebar {
  background: #ffffff;
}

.window-titlebar.dragging {
