}

.window-title-text .window-extra {
  font-weight: 400;
  color: #666;
  margin-left: 4px;
}

/* ---------- Window Controls ---------- */
.window-controls {
  display: flex;
  gap: 8px;
  align-items: center;
}

.window-close-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: #666;
  transition: background 0.15s ease, color 0.15s ease;
}

.window-close-btn:hover {
  background: #e0e0e0;
  color: #333;
}

.window.focused .window-close-btn {
  color: #1e1e1e;
}

/* ---------- Resize Handle ---------- */
.window-resize-handle {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
}

/* ---------- Window Content ---------- */
.window-content {
  flex: 1;
  overflow: auto;
  padding: 12px;
  font-size: 14px;
  background: #ffffff;
}

/* ---------- Placeholder content ---------- */
.placeholder-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: #888;
  gap: 12px;
}

.placeholder-content .placeholder-icon {
  font-size: 48px;
  opacity: 0.5;
}

.placeholder-content .placeholder-text {
  font-size: 16px;
}

/* ============================================================
   Taskbar
   ============================================================ */
#taskbar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: rgba(243, 243, 243, 0.85);
  backdrop-filter: blur(20px);
