/* ============================================================
   Calculator
   ============================================================ */

#calculator-content {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
  background: #f5f5f5;
}

.calculator-display {
  background: #1e1e1e;
  color: #ffffff;
  font-size: 36px;
  font-weight: 300;
  text-align: right;
  padding: 16px 20px;
  min-height: 80px;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  word-break: break-all;
  line-height: 1.2;
  overflow: hidden;
}

.calculator-display .calc-expression {
  font-size: 14px;
  color: #999;
  margin-bottom: 4px;
}

.calculator-display .calc-current {
  font-size: 36px;
  transition: font-size 0.1s ease;
}

.calculator-display .calc-current.small {
  font-size: 24px;
}

.calculator-display .calc-current.error {
  color: #ff5252;
  font-size: 28px;
}

.calculator-buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  padding: 8px;
  flex: 1;
}

.calc-btn {
  border: none;
  background: #e8e8e8;
  border-radius: 8px;
  font-size: 20px;
  font-weight: 400;
  color: #1e1e1e;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  transition: background 0.1s ease;
  user-select: none;
  -webkit-user-select: none;
}

.calc-btn:hover {
  background: #d8d8d8;
}

.calc-btn:active {
  background: #c8c8c8;
}

.calc-btn.operator {
  background: #ff9800;
  color: #ffffff;
}

.calc-btn.operator:hover {
  background: #f57c00;
}

.calc-btn.operator:active {
  background: #f57c00;
}

.calc-btn.operator.active {
  background: #f57c00;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2);
}

.calc-btn.equals {
  background: #0078d4;
  color: #ffffff;
}

.calc-btn.equals:hover {
  background: #005a9e;
}

.calc-btn.equals:active {
  background: #005a9e;
}

.calc-btn.function-btn {
  background: #c8c8c8;
  color: #1e1e1e;
}

.calc-btn.function-btn:hover {
  background: #b8b8b8;
}

.calc-btn.function-btn:active {
  background: #a8a8a8;
}

.calc-btn.clear {
  background: #ff5252;
  color: #ffffff;
}

.calc-btn.clear:hover {
  background: #d32f2f;
}

.calc-btn.clear:active {
  background: #d32f2f;
}

.calc-btn.zero {
  grid-column: span 1;
}

