+  } else if (key === "Escape" || key === "Delete") {
+    e.preventDefault();
+    handleCalcButton("C");
+  } else if (key === "Backspace") {
+    e.preventDefault();
+    handleBackspace();
+  }
+}
+
+/**
+ * Handle backspace: remove last digit from current display.
+ */
+function handleBackspace() {
+  if (calc.error) {
+    clearCalc();
+    return;
+  }
+  if (calc.waitingForOperand || calc.justEvaluated) {
+    return;
