/**
 * Handle a calculator button press.
 */
function handleCalcButton(label) {
  if (label === "C") {
    clearCalc();
    return;
  }

  if (label === "±") {
    toggleSign();
    return;
  }

  if (label === "%") {
    handlePercent();
    return;
  }

  if ("÷×−+".includes(label)) {
    handleOperator(label);
    return;
  }

  if (label === "=") {
    handleEquals();
    return;
  }

  // Digits and decimal point
  if ("0123456789.".includes(label)) {
    handleDigit(label);
  }
}

