#windows-container {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
}

/* ============================================================
   Window
   ============================================================ */
.window {
  position: absolute;
  min-width: 320px;
  min-height: 200px;
  background: #f5f5f5;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
