/* ============================================================
   Notepad
   ============================================================ */
#notepad-content {
  display: flex;
  height: 100%;
  background: #ffffff;
}

/* Sidebar */
.notepad-sidebar {
  width: 180px;
  min-width: 180px;
  background: #f0f0f0;
  border-right: 1px solid #e0e0e0;
  display: flex;
  flex-direction: column;
}

.notepad-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  border-bottom: 1px solid #e0e0e0;
  background: #e8e8e8;
}

.notepad-sidebar-title {
  font-size: 13px;
  font-weight: 600;
  color: #1e1e1e;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.notepad-sidebar-btn {
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  color: #555;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s ease, color 0.1s ease;
}

.notepad-sidebar-btn:hover {
  background: rgba(0, 0, 0, 0.08);
  color: #1e1e1e;
}

/* Document list */
.notepad-doc-list {
  flex: 1;
  overflow-y: auto;
  padding: 4px 0;
}

.notepad-doc-item {
  padding: 8px 12px;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.1s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-left: 3px solid transparent;
}

.notepad-doc-item:hover {
  background: rgba(0, 0, 0, 0.04);
}

.notepad-doc-item.active {
  background: #e3f0ff;
  border-left-color: #0078d4;
  color: #1e1e1e;
  font-weight: 500;
}

.notepad-doc-item .notepad-doc-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  display: block;
}

/* Notepad actions bar */
.notepad-actions {
  display: flex;
  align-items: center;
  padding: 6px 8px;
  gap: 4px;
  border-top: 1px solid #e0e0e0;
  background: #e8e8e8;
}

.notepad-action-btn {
  height: 28px;
  padding: 0 10px;
  border: none;
  background: #e0e0e0;
  border-radius: 4px;
  cursor: pointer;
  font-size: 11px;
  font-weight: 500;
  color: #1e1e1e;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: background 0.1s ease;
}

.notepad-action-btn:hover {
  background: #d0d0d0;
}

.notepad-action-btn:active {
  background: #c0c0c0;
}

.notepad-action-btn.danger {
  background: #ffe0e0;
  color: #d32f2f;
}

.notepad-action-btn.danger:hover {
  background: #ffcdd2;
}

/* Editor area */
.notepad-editor-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: #ffffff;
}

.notepad-editor-header {
  padding: 4px 12px;
  font-size: 12px;
  color: #666;
  border-bottom: 1px solid #e8e8e8;
  background: #fafafa;
}

.notepad-editor-header .notepad-doc-status {
  font-style: italic;
}

.notepad-editor-header .notepad-doc-status.modified {
  color: #f57c00;
}

.notepad-textarea {
  flex: 1;
  width: 100%;
  border: none;
  outline: none;
  resize: none;
  padding: 12px;
  font-family: "Consolas", "Courier New", monospace;
  font-size: 14px;
  line-height: 1.6;
  color: #1e1e1e;
  background: #ffffff;
  tab-size: 4;
}

.notepad-textarea::placeholder {
  color: #bbb;
}

/* Empty state */
.notepad-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: #aaa;
  gap: 8px;
}

.notepad-empty .empty-icon {
  font-size: 48px;
  opacity: 0.4;
}

.notepad-empty .empty-text {
  font-size: 14px;
}

