document.addEventListener("DOMContentLoaded", () => {
  init();

  // Close context menu / wallpaper picker on outside click
  document.addEventListener("click", (e) => {
    hideContextMenu();
    hideWallpaperPicker();
  });

  // Prevent context menu on the desktop
  document.getElementById("desktop").addEventListener("contextmenu", (e) => {
    e.preventDefault();
    showContextMenu(e.clientX, e.clientY);
  });
});

/* ============================================================
   Browser OS — Stylesheet
   Modern flat design (Windows 11 / macOS style)
   ============================================================ */

/* ---------- Reset ---------- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  color: #1e1e1e;
  user-select: none;
  -webkit-user-select: none;
}

/* ============================================================
   Desktop
   ============================================================ */
#desktop {
  position: fixed;
  inset: 0;
  z-index: 0;
  background: #3a6b8c;
  transition: background 0.3s ease;
}

/* ---------- Wallpaper presets ---------- */
/* 1. Default teal */
.wallpaper-0 {
  background: linear-gradient(135deg, #1a5276, #3a6b8c, #1a5276);
}

/* 2. Purple */
.wallpaper-1 {
  background: linear-gradient(135deg, #4a148c, #7b1fa2, #4a148c);
}

/* 3. Sunset orange */
.wallpaper-2 {
  background: linear-gradient(135deg, #bf360c, #e65100, #ff6e40);
}

/* 4. Forest green */
.wallpaper-3 {
  background: linear-gradient(135deg, #1b5e20, #388e3c, #1b5e20);
}

/* 5. Midnight blue */
.wallpaper-4 {
  background: linear-gradient(135deg, #0d1b2a, #1b263b, #0d1b2a);
}

/* 6. Rose */
.wallpaper-5 {
  background: linear-gradient(135deg, #880e4f, #c2185b, #880e4f);
}

/* 7. Light solid */
.wallpaper-6 {
  background: #e8e8e8;
}

/* 8. Dot pattern */
.wallpaper-7 {
  background: #263238;
  background-image: radial-gradient(circle, #37474f 1px, transparent 1px);
  background-size: 24px 24px;
}

/* ============================================================
   Desktop Icons
   ============================================================ */
#desktop-icons {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 90px;
  border-radius: 8px;
  cursor: pointer;
  padding: 8px 4px;
  transition: background 0.15s ease;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.12);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.2);
}

.desktop-icon-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 6px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
}

.desktop-icon-label {
