}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.12);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.2);
}

.desktop-icon-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 6px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
}

.desktop-icon-label {
