  color: #ffffff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  text-align: center;
  word-wrap: break-word;
  line-height: 1.3;
}

/* Icon colors */
.desktop-icon[data-app="notepad"] .desktop-icon-icon {
  background: #2196F3;
}

.desktop-icon[data-app="calculator"] .desktop-icon-icon {
  background: #FF5722;
}

