edits.newText:
/* Game container for overlay positioning */
.minesweeper-game-container {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

/* ============================================================
   Spider Solitaire
   ============================================================ */
#spider-content {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
  background: #0a5e2b;
  overflow: hidden;
}

/* Spider top bar */
.spider-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 36px;
  padding: 0 8px;
  background: #094a23;
  flex-shrink: 0;
}

.spider-top-bar-title {
  font-size: 13px;
  font-weight: 600;
  color: #ffffff;
}

.spider-stock-area {
  display: flex;
  align-items: center;
  gap: 4px;
}

.spider-stock-btn {
  width: 36px;
  height: 48px;
  border: 2px solid #2e7d32;
  border-radius: 6px;
  background: linear-gradient(135deg, #1b5e20, #2e7d32);
  color: #ffffff;
  font-size: 18px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}

.spider-stock-btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #2e7d32, #388e3c);
}

.spider-stock-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.spider-stock-btn.deal {
  font-size: 12px;
  font-weight: 600;
  flex-direction: column;
  gap: 1px;
  padding: 2px;
  line-height: 1.1;
}

.spider-stock-count {
  font-size: 11px;
  color: #c8e6c9;
  font-weight: 500;
}

.spider-game-container {
  flex: 1;
  display: flex;
  gap: 4px;
  padding: 8px;
  overflow-x: auto;
  overflow-y: hidden;
}

/* Spider column */
.spider-column {
  display: flex;
  flex-direction: column;
  min-width: 70px;
  max-width: 80px;
  width: 80px;
  flex-shrink: 0;
  position: relative;
}

/* Card styling */
.spider-card {
  width: 100%;
  height: 36px;
  border: 1px solid #555;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  position: relative;
  z-index: 1;
  transition: box-shadow 0.1s ease;
}

.spider-card.face-down {
  background: linear-gradient(135deg, #1565c0, #1976d2);
  border-color: #0d47a1;
  color: transparent;
}

.spider-card.face-down::after {
  content: "♠";
  position: absolute;
  color: rgba(255, 255, 255, 0.15);
  font-size: 28px;
  font-weight: 700;
}

.spider-card.face-up {
  background: #ffffff;
  border-color: #999;
  color: #1e1e1e;
}

.spider-card.face-up.drag-over {
  box-shadow: 0 0 8px rgba(0, 120, 212, 0.6);
  border-color: #0078d4;
}

.spider-card.selected {
  box-shadow: 0 0 6px rgba(0, 120, 212, 0.8), 0 2px 4px rgba(0, 0, 0, 0.2);
  border-color: #0078d4;
}

.spider-card.dragging {
  opacity: 0.6;
  z-index: 999;
}

.spider-card .card-rank {
  font-size: 16px;
}

.spider-card .card-suit {
  font-size: 14px;
}

/* Column drop indicator */
.spider-column-drop-zone {
  position: absolute;
  inset: 0;
  border: 2px dashed transparent;
  border-radius: 6px;
  pointer-events: none;
  z-index: 10;
  transition: border-color 0.15s ease;
}

.spider-column-drop-zone.drag-over {
  border-color: #0078d4;
  background: rgba(0, 120, 212, 0.1);
}

/* Stock pile card */
.spider-stock-card {
  width: 36px;
  height: 48px;
  border: 2px solid #2e7d32;
  border-radius: 6px;
  background: linear-gradient(135deg, #1565c0, #1976d2);
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s ease;
}

.spider-stock-card:hover {
  transform: scale(1.05);
}

/* Win overlay */
.spider-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.spider-overlay-content {
  background: #fff;
  border-radius: 12px;
  padding: 32px 40px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

.spider-overlay-content h2 {
  font-size: 28px;
  margin-bottom: 8px;
}

.spider-overlay-content p {
  font-size: 14px;
  color: #666;
  margin-bottom: 16px;
}

.spider-overlay-content button {
  height: 36px;
  padding: 0 24px;
  border: none;
  background: #0078d4;
  color: #fff;
  border-radius: 6px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: background 0.1s ease;
}

.spider-overlay-content button:hover {
  background: #005a9e;
}

/* New Game button */
.spider-new-game-btn {
  height: 28px;
  padding: 0 12px;
  border: 1px solid #2e7d32;
  background: #1b5e20;
  color: #ffffff;
  border-radius: 4px;
  cursor: pointer;
  font-size: 11px;
  font-weight: 500;
  transition: background 0.15s ease;
}

.spider-new-game-btn:hover {
  background: #2e7d32;
}

